import{_ as a,o as e,c as d,ag as r}from"./chunks/framework.DB9Ll7VW.js";const g=JSON.parse('{"title":"All add-ons","description":"A flat, scannable catalog of every Sikshya Pro add-on — premium gateways, course bundles, certificates, gradebook, marketplace, multilingual, and more. One card per feature with a direct upgrade link.","frontmatter":{"title":"All add-ons","description":"A flat, scannable catalog of every Sikshya Pro add-on — premium gateways, course bundles, certificates, gradebook, marketplace, multilingual, and more. One card per feature with a direct upgrade link."},"headers":[],"relativePath":"addons.md","filePath":"addons.md","lastUpdated":1778327862000}'),s={name:"addons.md"};function l(i,t,n,c,o,p){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="all-add-ons" tabindex="-1">All add-ons <a class="header-anchor" href="#all-add-ons" aria-label="Permalink to &quot;All add-ons&quot;">​</a></h1><p>This is the <strong>flat catalog</strong> — every Sikshya Pro add-on plus every premium gateway, on a single page. Use the <a href="/docs/third-party-integrations">Pro add-ons overview</a> for grouped, narrative explanations.</p><div class="doc-pro-callout"><span class="doc-pro-pill">Pro</span><span><strong>Everything below is a paid add-on</strong> (Sikshya Pro). Plans are <span class="doc-tier-pill doc-tier-pill--starter">Starter</span>, <span class="doc-tier-pill doc-tier-pill--growth">Growth</span>, and <span class="doc-tier-pill doc-tier-pill--scale">Scale</span> — <strong>each card’s badge is the minimum plan</strong> that includes that add-on. Activate a license under <em>Sikshya → License</em> and toggle add-ons under <em>Sikshya → Add-ons</em>.</span><a class="doc-pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya-lms/pricing/" target="_blank" rel="noopener">View pricing →</a></div><p class="doc-tier-legend"><strong>Badge legend:</strong> <span class="doc-tier-pill doc-tier-pill--starter">Starter</span> = available on <strong>Starter</strong> and every higher plan. <span class="doc-tier-pill doc-tier-pill--growth">Growth</span> = needs <strong>Growth</strong> or <strong>Scale</strong>. <span class="doc-tier-pill doc-tier-pill--scale">Scale</span> = <strong>Scale</strong> only. Higher plans always include everything from lower tiers.</p><h2 id="plan-matrix" tabindex="-1">Which plan unlocks which add-on? <a class="header-anchor" href="#plan-matrix" aria-label="Permalink to &quot;Which plan unlocks which add-on? {#plan-matrix}&quot;">​</a></h2><p>Sikshya Pro ships in three tiers. Each add-on lists its <strong>minimum tier</strong> — anything above unlocks it too.</p><table tabindex="0"><thead><tr><th>Tier</th><th>Who it&#39;s for</th><th>Highlights</th></tr></thead><tbody><tr><td><strong>Starter</strong></td><td>Independent creators, single-instructor sites</td><td>Reviews &amp; ratings, Instructor dashboard, Content drip, Drip emails, Prerequisites, Calendar, <strong>all 7 premium gateways</strong></td></tr><tr><td><strong>Growth</strong></td><td>Small academies, paid course shops</td><td>Everything in Starter <strong>plus</strong> Bundles, Subscriptions, Multi-instructor, Live classes, SCORM/H5P, Advanced assignments, Question banks, Gradebook, Advanced certificates, Coupons, Dynamic checkout fields, Social login, Analytics exports, Activity log, Branded delivery, Email customisation, CRM automation, Email marketing sync</td></tr><tr><td><strong>Scale</strong></td><td>Marketplaces, agencies, enterprise</td><td>Everything in Growth <strong>plus</strong> Webhooks, Zapier, Public API &amp; API keys, Multi-vendor marketplace, White label, Multisite tools, WPML / Weglot multilingual, Enterprise reporting</td></tr></tbody></table><blockquote><p>Already on a higher tier? Every add-on a lower tier includes is also yours. Check the per-add-on tier label on each card below.</p></blockquote><h3 id="add-on-→-tier-matrix-alphabetical" tabindex="-1">Add-on → tier matrix (alphabetical) <a class="header-anchor" href="#add-on-→-tier-matrix-alphabetical" aria-label="Permalink to &quot;Add-on → tier matrix (alphabetical)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Add-on</th><th style="text-align:center;">Starter</th><th style="text-align:center;">Growth</th><th style="text-align:center;">Scale</th></tr></thead><tbody><tr><td>Advanced analytics &amp; exports</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Advanced assignments</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Advanced certificates (builder, QR, verification)</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Advanced coupons &amp; upsells</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Advanced quiz types &amp; question banks</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Authorize.Net gateway</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Bank Transfer gateway</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Branded email delivery (ESP + templates)</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Calendar</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Content drip &amp; scheduled unlock</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Course bundles</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Course discussions / Q&amp;A</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Course reviews &amp; ratings</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>CRM email automation</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Drip &amp; automation emails</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Dynamic checkout fields</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Email advanced customization</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Email marketing (Mailchimp / MailerLite)</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Enterprise reporting</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td></tr><tr><td>Gradebook</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Instructor dashboard</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Live classes (Zoom / Meet)</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Mollie gateway</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Multi-instructor &amp; co-authors</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Multi-vendor marketplace</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td></tr><tr><td>Multilingual (WPML / Weglot)</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td></tr><tr><td>Multisite &amp; network license tools</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td></tr><tr><td>Paystack gateway</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Prerequisites</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Public API &amp; API keys</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td></tr><tr><td>Razorpay gateway</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>SCORM / H5P</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Social login</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Square gateway</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Stripe gateway</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Student activity log</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Subscriptions &amp; memberships</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Webhooks</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td></tr><tr><td>White label &amp; branding</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td></tr><tr><td>Zapier</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td></tr></tbody></table><blockquote><p>Tier names may vary slightly on the <a href="https://mantrabrain.com/plugins/sikshya-lms/pricing/" target="_blank" rel="noreferrer">pricing page</a> — always treat that page as the source of truth for what&#39;s bundled and the latest seat counts.</p></blockquote><h2 id="premium-payment-gateways" tabindex="-1">Premium payment gateways <a class="header-anchor" href="#premium-payment-gateways" aria-label="Permalink to &quot;Premium payment gateways&quot;">​</a></h2><div class="doc-addon-grid"><div class="doc-addon-card"><h3 class="doc-addon-card__title">Stripe <span class="doc-tier-pill doc-tier-pill--starter">Starter</span></h3><p class="doc-addon-card__copy">Cards, Apple Pay, Google Pay, SCA / 3-D Secure 2. Save card for subscription billing.</p><a class="doc-addon-card__cta" href="/payment-settings#stripe">Setup guide →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Razorpay <span class="doc-tier-pill doc-tier-pill--starter">Starter</span></h3><p class="doc-addon-card__copy">Cards, UPI, netbanking, wallets — primary choice for INR.</p><a class="doc-addon-card__cta" href="/payment-settings#razorpay">Setup guide →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Mollie <span class="doc-tier-pill doc-tier-pill--starter">Starter</span></h3><p class="doc-addon-card__copy">European-first gateway: iDEAL, Bancontact, SEPA, cards.</p><a class="doc-addon-card__cta" href="/payment-settings#mollie">Setup guide →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Paystack <span class="doc-tier-pill doc-tier-pill--starter">Starter</span></h3><p class="doc-addon-card__copy">Cards, Bank Transfer, USSD, Mobile Money. Primary for Nigeria, Ghana, Kenya, ZA.</p><a class="doc-addon-card__cta" href="/payment-settings#paystack">Setup guide →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Square <span class="doc-tier-pill doc-tier-pill--starter">Starter</span></h3><p class="doc-addon-card__copy">Cards via Square — useful when you also use Square&#39;s POS for in-person classes.</p><a class="doc-addon-card__cta" href="/payment-settings#square">Setup guide →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Authorize.Net <span class="doc-tier-pill doc-tier-pill--starter">Starter</span></h3><p class="doc-addon-card__copy">Long-running US gateway. AVS / CVV, recurring tokens.</p><a class="doc-addon-card__cta" href="/payment-settings#authorize-net">Setup guide →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Bank Transfer <span class="doc-tier-pill doc-tier-pill--starter">Starter</span></h3><p class="doc-addon-card__copy">Manual / wire-transfer flow. Sikshya creates a &quot;Pending payment&quot; order and shows your bank details.</p><a class="doc-addon-card__cta" href="/payment-settings#bank-transfer">Setup guide →</a></div></div><h2 id="build-curriculum-assets" tabindex="-1">Build (curriculum &amp; assets) <a class="header-anchor" href="#build-curriculum-assets" aria-label="Permalink to &quot;Build (curriculum &amp; assets)&quot;">​</a></h2><div class="doc-addon-grid"><div class="doc-addon-card"><h3 class="doc-addon-card__title">Course bundles <span class="doc-tier-pill doc-tier-pill--growth">Growth</span></h3><p class="doc-addon-card__copy">Sell several courses for one bundled price (&quot;bootcamp pack&quot;). Buyers auto-enrolled in every course.</p><a class="doc-addon-card__cta" href="/third-party-integrations#course-bundles">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Course reviews &amp; ratings <span class="doc-tier-pill doc-tier-pill--starter">Starter</span></h3><p class="doc-addon-card__copy">Star ratings + written reviews on the course page, with admin moderation. Plan: Starter.</p><a class="doc-addon-card__cta" href="/third-party-integrations#course-reviews-ratings">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Course discussions / Q&amp;A <span class="doc-tier-pill doc-tier-pill--growth">Growth</span></h3><p class="doc-addon-card__copy">In-course threads + Q&amp;A panel with instructor moderation. Great for cohort programs.</p><a class="doc-addon-card__cta" href="/third-party-integrations#course-discussions-qa">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Multi-instructor &amp; co-authors <span class="doc-tier-pill doc-tier-pill--growth">Growth</span></h3><p class="doc-addon-card__copy">Multiple instructors per course (Owner / Editor / Grader). Per-course revenue split.</p><a class="doc-addon-card__cta" href="/third-party-integrations#multi-instructor-co-authors">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Instructor dashboard <span class="doc-tier-pill doc-tier-pill--starter">Starter</span></h3><p class="doc-addon-card__copy">Focused home for the Sikshya Instructor role — courses, enrollments, earnings — without exposing wp-admin.</p><a class="doc-addon-card__cta" href="/third-party-integrations#instructor-dashboard">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Live classes (Zoom / Meet) <span class="doc-tier-pill doc-tier-pill--growth">Growth</span></h3><p class="doc-addon-card__copy">Pin a Zoom or Google Meet URL to a lesson. Rotate the URL without re-publishing.</p><a class="doc-addon-card__cta" href="/third-party-integrations#live-classes-zoom-meet-classroom">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">SCORM / H5P <span class="doc-tier-pill doc-tier-pill--growth">Growth</span></h3><p class="doc-addon-card__copy">Embed packaged SCORM 1.2 / 2004 content or H5P interactives as a lesson with progress tracked via SCORM API.</p><a class="doc-addon-card__cta" href="/third-party-integrations#scorm-h5p">Details →</a></div></div><h2 id="teach-assessment-automation-journey" tabindex="-1">Teach (assessment, automation, journey) <a class="header-anchor" href="#teach-assessment-automation-journey" aria-label="Permalink to &quot;Teach (assessment, automation, journey)&quot;">​</a></h2><div class="doc-addon-grid"><div class="doc-addon-card"><h3 class="doc-addon-card__title">Content drip &amp; scheduled unlock <span class="doc-tier-pill doc-tier-pill--starter">Starter</span></h3><p class="doc-addon-card__copy">Release lessons by date, X-days-from-enrollment, or cohort start. Plan: Starter.</p><a class="doc-addon-card__cta" href="/third-party-integrations#content-drip-scheduled-unlock">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Drip &amp; automation emails <span class="doc-tier-pill doc-tier-pill--starter">Starter</span></h3><p class="doc-addon-card__copy">&quot;Lesson unlocked&quot;, &quot;Course unlocked&quot;, weekly digest emails wired to drip rules.</p><a class="doc-addon-card__cta" href="/third-party-integrations#drip-automation-emails">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Prerequisites <span class="doc-tier-pill doc-tier-pill--starter">Starter</span></h3><p class="doc-addon-card__copy">Require chosen lessons or whole courses to be completed before the next step unlocks.</p><a class="doc-addon-card__cta" href="/third-party-integrations#prerequisites-lessons-courses">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Calendar <span class="doc-tier-pill doc-tier-pill--starter">Starter</span></h3><p class="doc-addon-card__copy">Dated schedule on the learner&#39;s account — enrollments, drip unlocks, due dates — with REST data.</p><a class="doc-addon-card__cta" href="/third-party-integrations#calendar">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Advanced assignments <span class="doc-tier-pill doc-tier-pill--growth">Growth</span></h3><p class="doc-addon-card__copy">Rubric grading, restricted file types, resubmissions, queue with filters (ungraded / late / failed).</p><a class="doc-addon-card__cta" href="/third-party-integrations#advanced-assignments">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Advanced quiz types &amp; banks <span class="doc-tier-pill doc-tier-pill--growth">Growth</span></h3><p class="doc-addon-card__copy">Reuse questions from a Question bank. Random pools, randomization, advanced types.</p><a class="doc-addon-card__cta" href="/third-party-integrations#advanced-quiz-types-question-banks">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Gradebook <span class="doc-tier-pill doc-tier-pill--growth">Growth</span></h3><p class="doc-addon-card__copy">Per-learner / per-course grades across quizzes &amp; graded assignments. CSV export, drilldown.</p><a class="doc-addon-card__cta" href="/third-party-integrations#gradebook">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Advanced certificates <span class="doc-tier-pill doc-tier-pill--growth">Growth</span></h3><p class="doc-addon-card__copy">Drag-and-drop builder, more merge fields, QR codes, public verify pages.</p><a class="doc-addon-card__cta" href="/third-party-integrations#advanced-certificates-builder-qr-verification">Details →</a></div></div><h2 id="sell-revenue-growth" tabindex="-1">Sell (revenue growth) <a class="header-anchor" href="#sell-revenue-growth" aria-label="Permalink to &quot;Sell (revenue growth)&quot;">​</a></h2><div class="doc-addon-grid"><div class="doc-addon-card"><h3 class="doc-addon-card__title">Subscriptions &amp; memberships <span class="doc-tier-pill doc-tier-pill--growth">Growth</span></h3><p class="doc-addon-card__copy">Recurring billing — monthly / yearly plans for member-only academy access.</p><a class="doc-addon-card__cta" href="/third-party-integrations#subscriptions-memberships">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Advanced coupons &amp; upsells <span class="doc-tier-pill doc-tier-pill--growth">Growth</span></h3><p class="doc-addon-card__copy">Min cart total, course / category restrictions, &quot;first-time buyer only&quot;, stacking guards.</p><a class="doc-addon-card__cta" href="/third-party-integrations#advanced-coupons-upsells">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Dynamic checkout fields <span class="doc-tier-pill doc-tier-pill--growth">Growth</span></h3><p class="doc-addon-card__copy">Configurable checkout questions (text / select / checkbox) with conditional visibility.</p><a class="doc-addon-card__cta" href="/third-party-integrations#dynamic-checkout-fields">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Social login <span class="doc-tier-pill doc-tier-pill--growth">Growth</span></h3><p class="doc-addon-card__copy">Sign-in with Google (and other providers). One click instead of password fatigue.</p><a class="doc-addon-card__cta" href="/third-party-integrations#social-login">Details →</a></div></div><h2 id="operate-analytics-reporting-audit" tabindex="-1">Operate (analytics, reporting, audit) <a class="header-anchor" href="#operate-analytics-reporting-audit" aria-label="Permalink to &quot;Operate (analytics, reporting, audit)&quot;">​</a></h2><div class="doc-addon-grid"><div class="doc-addon-card"><h3 class="doc-addon-card__title">Advanced analytics &amp; exports <span class="doc-tier-pill doc-tier-pill--growth">Growth</span></h3><p class="doc-addon-card__copy">Detailed enrollment / progress / revenue exports for Excel and Sheets, plus learner self-export.</p><a class="doc-addon-card__cta" href="/third-party-integrations#advanced-analytics-exports">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Student activity log <span class="doc-tier-pill doc-tier-pill--growth">Growth</span></h3><p class="doc-addon-card__copy">Timeline of milestones — enrollment, completions, attempts, submissions. Configurable retention.</p><a class="doc-addon-card__cta" href="/third-party-integrations#student-activity-log">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Enterprise reporting <span class="doc-tier-pill doc-tier-pill--scale">Scale</span></h3><p class="doc-addon-card__copy">Weekly KPI rollup emails for inbox-friendly executive snapshots. Plan: Scale.</p><a class="doc-addon-card__cta" href="/third-party-integrations#enterprise-reporting">Details →</a></div></div><h2 id="communicate-email-marketing-automation" tabindex="-1">Communicate (email, marketing, automation) <a class="header-anchor" href="#communicate-email-marketing-automation" aria-label="Permalink to &quot;Communicate (email, marketing, automation)&quot;">​</a></h2><div class="doc-addon-grid"><div class="doc-addon-card"><h3 class="doc-addon-card__title">Branded email delivery <span class="doc-tier-pill doc-tier-pill--growth">Growth</span></h3><p class="doc-addon-card__copy">First-class ESP setup (SendGrid-style) plus a branded multi-template kit (header, footer, accent, logo).</p><a class="doc-addon-card__cta" href="/third-party-integrations#professional-email-delivery-branded-templates">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Email advanced customization <span class="doc-tier-pill doc-tier-pill--growth">Growth</span></h3><p class="doc-addon-card__copy">Per-template HTML overrides, extra layout slots, conditional content blocks.</p><a class="doc-addon-card__cta" href="/third-party-integrations#email-advanced-customization">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">CRM email automation <span class="doc-tier-pill doc-tier-pill--growth">Growth</span></h3><p class="doc-addon-card__copy">Trigger sequences (Day 0 → 3 → 7) on enrollment, completion, abandoned cart.</p><a class="doc-addon-card__cta" href="/third-party-integrations#crm-email-automation">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Email marketing sync <span class="doc-tier-pill doc-tier-pill--growth">Growth</span></h3><p class="doc-addon-card__copy">Sync enrollments / completions to Mailchimp or MailerLite lists / segments automatically.</p><a class="doc-addon-card__cta" href="/third-party-integrations#email-marketing-mailchimp-mailerlite">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Webhooks <span class="doc-tier-pill doc-tier-pill--scale">Scale</span></h3><p class="doc-addon-card__copy">Signed JSON to your HTTPS endpoints whenever LMS events fire (purchase, enrollment, completion, certificate). Plan: Scale.</p><a class="doc-addon-card__cta" href="/third-party-integrations#webhooks">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Zapier <span class="doc-tier-pill doc-tier-pill--scale">Scale</span></h3><p class="doc-addon-card__copy">First-class Zapier triggers and actions. Sikshya events fan out into thousands of Zaps. Plan: Scale.</p><a class="doc-addon-card__cta" href="/third-party-integrations#zapier">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Public API &amp; API keys <span class="doc-tier-pill doc-tier-pill--scale">Scale</span></h3><p class="doc-addon-card__copy">Issue revocable API keys for partners and bespoke integrations. Scoped permissions over REST. Plan: Scale.</p><a class="doc-addon-card__cta" href="/third-party-integrations#public-api-api-keys">Details →</a></div></div><h2 id="scale-marketplace-branding-enterprise" tabindex="-1">Scale (marketplace, branding, enterprise) <a class="header-anchor" href="#scale-marketplace-branding-enterprise" aria-label="Permalink to &quot;Scale (marketplace, branding, enterprise)&quot;">​</a></h2><div class="doc-addon-grid"><div class="doc-addon-card"><h3 class="doc-addon-card__title">Multi-vendor marketplace <span class="doc-tier-pill doc-tier-pill--scale">Scale</span></h3><p class="doc-addon-card__copy">Open the academy to many independent vendors — storefronts, per-vendor commission, payouts. Plan: Scale.</p><a class="doc-addon-card__cta" href="/third-party-integrations#multi-vendor-marketplace">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">White label &amp; branding <span class="doc-tier-pill doc-tier-pill--scale">Scale</span></h3><p class="doc-addon-card__copy">Replace Sikshya labels with your own brand (logo, naming, optional &quot;powered by&quot; toggle). Plan: Scale.</p><a class="doc-addon-card__cta" href="/third-party-integrations#white-label-branding">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Multisite &amp; network license <span class="doc-tier-pill doc-tier-pill--scale">Scale</span></h3><p class="doc-addon-card__copy">Manage license slots across many subsites of a WordPress multisite network from one place. Plan: Scale.</p><a class="doc-addon-card__cta" href="/third-party-integrations#multisite-network-license-tools">Details →</a></div><div class="doc-addon-card"><h3 class="doc-addon-card__title">Multilingual (WPML / Weglot) <span class="doc-tier-pill doc-tier-pill--scale">Scale</span></h3><p class="doc-addon-card__copy">Bridge Sikshya&#39;s interface strings into WPML / Weglot translation stacks. Plan: Scale.</p><a class="doc-addon-card__cta" href="/third-party-integrations#multilingual-wpml-weglot">Details →</a></div></div><h2 id="how-add-ons-turn-on" tabindex="-1">How add-ons turn on <a class="header-anchor" href="#how-add-ons-turn-on" aria-label="Permalink to &quot;How add-ons turn on&quot;">​</a></h2><ol class="step-list"><li>Install <strong>Sikshya Pro</strong> alongside the free Sikshya plugin.</li><li>Activate your license in <span class="screen-path">Sikshya → License</span>.</li><li>Open <span class="screen-path">Sikshya → Add-ons</span>, search by name or category, click the toggle.</li><li>The relevant admin menus / settings panels appear automatically.</li></ol><blockquote><p>Disabling an add-on hides its UI but <strong>keeps your data</strong> so re-enabling later restores everything.</p></blockquote><h2 id="where-to-read-more" tabindex="-1">Where to read more <a class="header-anchor" href="#where-to-read-more" aria-label="Permalink to &quot;Where to read more&quot;">​</a></h2><ul><li><a href="/docs/third-party-integrations">Pro add-ons overview</a> — grouped by what they do.</li><li><a href="/docs/payment-settings">Payments &amp; gateways</a> — gateway-by-gateway setup.</li><li><a href="/docs/email-settings">Email &amp; notifications</a> — Pro email automation details.</li><li><a href="https://mantrabrain.com/plugins/sikshya-lms/pricing/" target="_blank" rel="noreferrer">Pricing</a> — pick the plan that includes the add-ons you need.</li></ul>',30)])])}const y=a(s,[["render",l]]);export{g as __pageData,y as default};
